SELECT 'count_eq_dopa' AS check_name, '7436' AS expected, count(*)::text AS actual FROM public.address_th_subdistrict
UNION ALL SELECT 'ids_md5_eq_dopa', '18892d7089a8755886b5b94a1a655cb9', md5(string_agg(id, ',' ORDER BY id)) FROM public.address_th_subdistrict
UNION ALL SELECT 'en_zero', '0', count(*)::text FROM public.address_th_subdistrict WHERE subdistrict_name_en = '0'
UNION ALL SELECT 'zip_zero_or_null', '0', count(*)::text FROM public.address_th_subdistrict WHERE zip_code IS NULL OR zip_code = 0
UNION ALL SELECT 'dup_name_in_district', '0', count(*)::text FROM (SELECT district_id, subdistrict_name_th FROM public.address_th_subdistrict GROUP BY 1, 2 HAVING count(*) > 1) z
